// Guides are autogenerated from docs/guides; the Reference tree is generated by `npm run apidocs`
// (.generated/sidebar.json), grouped by namespace and area.
const { existsSync, readFileSync } = require('node:fs');

const reference = existsSync('./.generated/sidebar.json') ? JSON.parse(readFileSync('./.generated/sidebar.json', 'utf8')) : [];

module.exports = {
  docs: [
    'index',
    {
      type: 'category',
      label: 'Guides',
      collapsible: false,
      items: [{ type: 'autogenerated', dirName: 'guides' }],
    },
    {
      type: 'category',
      label: 'Reference',
      collapsible: false,
      link: existsSync('./docs/reference/index.md') ? { type: 'doc', id: 'reference/index' } : undefined,
      items: reference,
    },
  ],
};
